using System;
using System.IO;
using System.Linq;
using CastleFight;
using Newtonsoft.Json.Linq;
using UnityEngine;
public static class HumanInventoryChecks {
    static int checks;static JObject data;
    static void Test(bool value,string name){checks++;if(!value)throw new Exception("Castle inventory: "+name);}
    static void Near(float value,float expected,string name,float tolerance=.02f)=>Test(Mathf.Abs(value-expected)<tolerance,name+" "+value+" / "+expected);
    static HumanMatch Game(){var m=new HumanMatch((JObject)data.DeepClone(),0);m.Gold[0]=100000;m.Gold[1]=0;m.Wood[0]=100000;foreach(var l in m.Lines){l.speed=0;l.regen=0;}return m;}
    static void Buy(HumanMatch m,string id){Test(m.BuyItem(0,m.ShopIndex(id),out var error),"buy "+id+" "+error);}
    static void Time(HumanMatch m,float seconds){for(int i=0;i<Mathf.RoundToInt(seconds/.05f);i++)m.Step(.05f);}
    static HumanMatch.Unit Unit(HumanMatch m,int team,Vector2 p,int kind=0){var u=m.Spawn(team,kind,p);u.onRoad=true;u.cooldown=1000;return u;}
    public static void Run() {
        checks=0;data=JObject.Parse(File.ReadAllText("Assets/Resources/pc-human.json"));var m=Game();Test(m.ShopItems.Count==9&&m.ItemCatalog["I002"]!=null,"nine castle items plus crafted multistaff");
        Test(!m.BuyItem(0,-1,out _)&&!m.BuyItem(2,0,out _),"reject invalid item/team");int rune=m.ShopIndex("I009");Test(m.Stock(0,rune).count==0&&!m.BuyItem(0,rune,out _),"no stock before 30 seconds");
        m.Elapsed=30;Test(m.Stock(0,rune).count==1,"stock appears at 30");float gold=m.Gold[0];Buy(m,"I009");Near(m.Gold[0],gold-400,"rune exact cost");Test(!m.BuyItem(0,rune,out _)&&m.Stock(1,rune).count==1,"stocks independent per team");
        m.Elapsed=209.99f;Test(m.Stock(0,rune).count==0,"stock not early");m.Elapsed=210;Test(m.Stock(0,rune).count==1,"stock regenerates at deadline");Buy(m,"I009");Test(m.Inventories[0].Used==2&&m.Inventories[0].slots.Count==1,"duplicates consume two physical slots");
        m.CastleHp[0]=4000;m.Builders[0].position=m.Builders[0].goal=HumanMatch.CastlePosition(0);Time(m,1);Near(m.CastleHp[0],4005.5f,"two repair runes stack plus natural regen",.06f);m.Builders[0].position=m.Builders[0].goal=new Vector2(-70,60);float hp=m.CastleHp[0];Time(m,1);Near(m.CastleHp[0]-hp,.5f,"repair rune has builder radius",.06f);
        var reserved=Game();reserved.Elapsed=30;reserved.Gold[0]=650;reserved.TryBuild(0,0,7,15,out _);Test(!reserved.BuyItem(0,reserved.ShopIndex("I00A"),out _),"shop respects construction reservation");
        var aura=Game();aura.Elapsed=30;Buy(aura,"I003");Buy(aura,"I00A");var soldier=Unit(aura,0,aura.Builders[0].position);Near(aura.InventoryDamage(soldier),1.33f,"drums damage");Near(aura.AttackSpeed(soldier),1.3f,"generator attack speed");aura.Lines[0].speed=9;Near(aura.MoveSpeed(soldier),10.35f,"generator movement speed");aura.Elapsed=930;Buy(aura,"I003");Near(aura.InventoryDamage(soldier),1.33f,"two drums do not stack");soldier.position=new Vector2(800,0);Near(aura.InventoryDamage(soldier),1,"drums limited by radius");Near(aura.AttackSpeed(soldier),1,"haste limited by radius");
        var boost=Game();boost.Elapsed=300;Buy(boost,"I008");var fighter=Unit(boost,0,Vector2.zero);Near(boost.InventoryDamage(fighter),2,"double damage immediate");Test(boost.Inventories[0].Used==0,"instant boost takes no slot");boost.Elapsed=600;Buy(boost,"I007");Near(boost.InventoryDamage(fighter),4,"strongest damage boost wins");Time(boost,29.1f);Near(boost.InventoryDamage(fighter),1,"boost expires after 29 seconds");
        var cap=Game();for(int i=0;i<6;i++){cap.Elapsed=30+180*i;Buy(cap,"I009");}Test(cap.Inventories[0].Used==6&&!cap.BuyItem(0,cap.ShopIndex("I003"),out _),"six slot capacity includes duplicate counts");Buy(cap,"I004");Test(cap.LegendaryLimit[0]==2&&cap.Inventories[0].Used==6,"cheese increases legendary limit with full inventory");
        var craft=Game();for(int i=0;i<4;i++){craft.Elapsed=30+300*i;Buy(craft,"I001");}Test(craft.Inventories[0].Used==1&&craft.Inventories[0].slots.Single().id=="I002","four staves become one multistaff");var victim=Unit(craft,1,craft.Builders[0].position+Vector2.right*10);victim.hp=victim.maxHp=5000;Time(craft,1.5f);Test(craft.ItemShots>=5&&craft.ItemShots<=6&&victim.hp<5000,"multistaff launches four real magic missiles per second");Near((5000-victim.hp)/60,Mathf.Round((5000-victim.hp)/60),"staff damage bypasses physical armor");
        var scroll=Game();scroll.Elapsed=30;Buy(scroll,"I005");scroll.Elapsed=210;Buy(scroll,"I005");var hurt=Unit(scroll,0,new Vector2(-100,0),scroll.Kind("h038"));hurt.hp=100;hurt.mana=0;var outside=Unit(scroll,0,new Vector2(-30,50));outside.hp=100;
        Test(!scroll.UseItem(0,0,-1,new Vector2(10000,0),out _),"invalid scroll point preserves charge");Test(scroll.UseItem(0,0,-1,hurt.position,out _),"point scroll cast");Near(hurt.hp,500,"scroll heals 400");Near(hurt.mana,200,"scroll restores 200 mana");Near(scroll.Stat(hurt,"armor"),8,"scroll adds eight armor");Near(outside.hp,100,"scroll does not affect outside radius");Test(scroll.Inventories[0].slots.Single().count==1&&!scroll.UseItem(0,0,-1,hurt.position,out _),"scroll charge consumed and shared cooldown blocks second");scroll.Elapsed=390;Buy(scroll,"I005");Test(!scroll.UseItem(0,0,-1,hurt.position,out _),"fresh purchase cannot reset shared cooldown");scroll.Units.Clear();Time(scroll,60.1f);Test(scroll.UseItem(0,0,-1,new Vector2(-100,0),out _),"scroll usable after full cooldown");
        var orb=Game();orb.Elapsed=899.99f;Test(!orb.BuyItem(0,orb.ShopIndex("I006"),out _),"lightning orb gated until 15 minutes");orb.Elapsed=900;Buy(orb,"I006");var source=orb.Builders[0].position;var first=Unit(orb,1,source+Vector2.right*8);var second=Unit(orb,1,source+Vector2.right*17);first.hp=first.maxHp=10000;second.hp=second.maxHp=10000;
        Test(!orb.UseItem(0,0,123456,source,out _),"orb rejects missing target");Test(orb.UseItem(0,0,first.id,first.position,out _),"orb targets enemy");Near(first.hp,9000,"orb first hit 1000");Near(second.hp,9100,"orb second hit 900");Test(orb.Inventories[0].slots.Count==1&&!orb.UseItem(0,0,first.id,first.position,out _),"orb reusable but cooldown enforced");
        orb.Surrender(0);Test(!orb.BuyItem(0,rune,out _)&&!orb.UseItem(0,0,first.id,first.position,out _),"shop and inventory disabled after result");
        File.WriteAllText("../Validation/PC/inventory-verification.json",new JObject {["status"]="PASS",["checks"]=checks,["shopItems"]=9,["inventoryCapacity"]=6,["source"]="Godot inventory.gd / shop_items.json / item_catalog.json"}.ToString());Debug.Log("CF_CASTLE_INVENTORY_PASS checks="+checks);
    }
}
